// Regenerates golden data. Usage: node scripts/sim-golden.mjs [file] [--set base|legacy-buildings|wedge]
// legacy-buildings must only ever be generated by code from before the wedge model (it pins the old behaviour).
import { mkdirSync, writeFileSync } from 'node:fs';
import { goldenFor } from '../test/golden-lib.js';
import { GOLDEN_SCENES, LEGACY_BUILDING_SCENES, WEDGE_SCENES } from '../test/golden-scenes.js';

const args = process.argv.slice(2);
const setIdx = args.indexOf('--set');
const set = setIdx >= 0 ? args[setIdx + 1] : 'base';
const scenes = { base: GOLDEN_SCENES, 'legacy-buildings': LEGACY_BUILDING_SCENES, wedge: WEDGE_SCENES }[set];
if (!scenes) throw new Error(`unknown set ${set}`);
const defaults = { base: 'test/golden/golden.json', 'legacy-buildings': 'test/golden/golden-legacy-buildings.json', wedge: 'test/golden/golden-wedge.json' };
const out = Object.fromEntries(Object.keys(scenes).map((name) => [name, goldenFor(name, scenes)]));
const file = args.find((a, i) => !a.startsWith('--') && args[i - 1] !== '--set') || defaults[set];
mkdirSync(new URL('../test/golden/', import.meta.url), { recursive: true });
writeFileSync(new URL(`../${file}`, import.meta.url), JSON.stringify(out));
console.log(`wrote ${file}`);
